"""Multi-source validation on independent public data (not generated by us), with an external baseline.

Test groups (each capped at --cap rows, stratified):
  jackhhao_jailbreak, spml_chatbot, geekyrakshit_injection, deepset (train+test), safeguard   published labels
  gandalf_vs_instructions   real 'ignore instructions' attempts vs human instructions (dolly, alpaca)
  injecagent_vs_notes       agent attacker instructions vs persona facts and user messages
  notes_D                   100 hand-style notes written by the authors' assistant (data/hand_notes.tsv)
  notes_A / notes_B / notes_C   LLM-written notes (data/llm_notes.jsonl test splits)
The last two paired groups have no published attack/benign labels in the same distribution, so source shortcuts
(topic, length) can inflate them; they are reported but flagged.

Scorers (all produce P(attack)):
  hybrid_shipped     models/classifier_hybrid.pkl, zero-shot (never trained on jackhhao, spml, geekyrakshit, gandalf,
                     injecagent, dolly, alpaca, oasst, synthetic persona; DID train on deepset/safeguard/persona_chat
                     slices, so those two groups are marked contaminated)
  hybrid_instr       models/classifier_hybrid_instr.pkl (adds hand_train.tsv)
  finetuned_instr    fine-tuned MiniLM (models/finetuned_minilm_instr.pt)
  protectai_deberta  protectai/deberta-v3-base-prompt-injection-v2, an independent published detector, zero-shot
  tfidf_loso, embed_loso   logistic regressions trained on EVERY OTHER source (leave-one-group-out)

Usage:  python -m scripts.run_multisource      Writes results_research/multisource.{json,md}
"""

import copy
import json
import random
from pathlib import Path

import numpy as np
import torch
import typer
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.linear_model import LogisticRegression
from sklearn.metrics import roc_auc_score, roc_curve

from driftguard.benchmark.labelling import load_benchmark
from driftguard.detector.features import FeatureExtractor, SemanticFeatureExtractor
from driftguard.detector.hybrid import load_detector, windows
from driftguard.security import normalise_text

app = typer.Typer()
MAXCH = 700


def jl(path: Path) -> list[dict]:
    return [json.loads(x) for x in path.read_text(encoding="utf-8").splitlines() if x.strip()]


def tsv(path: Path) -> list[tuple[int, str]]:
    return [(int(l.split("\t", 1)[0] == "0"), l.split("\t", 1)[1]) for l in path.read_text(encoding="utf-8").splitlines() if "\t" in l]


def load_sources(ext: Path, ext2: Path, notes: Path, hand: Path) -> dict[str, list[tuple[str, int]]]:
    S: dict[str, list[tuple[str, int]]] = {}
    for p in sorted(ext2.glob("*.jsonl")):
        S[p.stem] = [(r["text"][:MAXCH], int(r["label"])) for r in jl(p)]
    d = jl(ext / "deepset_prompt_injections_train.jsonl") + jl(ext / "deepset_prompt_injections_test.jsonl")
    S["deepset"] = [(r["text"][:MAXCH], int(r["label"])) for r in d]
    S["safeguard"] = [(r["text"][:MAXCH], int(r["label"])) for r in jl(ext / "safeguard_prompt_injection_test.jsonl")]
    S["notes_D"] = [(t[:MAXCH], y) for y, t in tsv(hand)]
    rows = jl(notes)
    for sp, name in (("test_a", "notes_A"), ("test_b", "notes_B"), ("test_c", "notes_C")):
        S[name] = [(r["text"][:MAXCH], int(r["label"] == 0)) for r in rows if r["split"] == sp]
    return S


def far_at_recall(y, p, target=0.9):
    fpr, tpr, _ = roc_curve(y, p)
    return float(fpr[np.argmax(tpr >= target)])


def boot_auc(y, p, rng, n=500):
    idx = np.arange(len(y))
    vals = []
    for _ in range(n):
        b = rng.choice(idx, len(idx))
        if 0 < y[b].sum() < len(b):
            vals.append(roc_auc_score(y[b], p[b]))
    return [float(np.percentile(vals, 2.5)), float(np.percentile(vals, 97.5))] if vals else [float("nan")] * 2


def subsample(pairs, cap, rng):
    pos = [p for p in pairs if p[1] == 1]
    neg = [p for p in pairs if p[1] == 0]
    k = min(cap // 2, len(pos), len(neg)) if pos and neg else 0
    if k == 0:
        return pairs[:cap]
    rng.shuffle(pos), rng.shuffle(neg)
    return pos[:k] + neg[:k]


@app.command()
def main(
    ext: Path = Path("data/external"), ext2: Path = Path("data/external2"),
    notes: Path = Path("data/llm_notes.jsonl"), hand: Path = Path("data/hand_notes.tsv"),
    train_extra: Path = Path("data/hand_train.tsv"), benchmark: Path = Path("data/benchmark_hard.jsonl"),
    cap: int = 400, loso_per_source: int = 1500, out: Path = Path("results_research"), seed: int = 0,
    only: str = typer.Option("", help="comma-separated group names to (re)run, e.g. injecagent_toolresp"),
    tag: str = typer.Option("", help="suffix for the output files, e.g. _tool"),
) -> None:
    rng = random.Random(seed)
    nrng = np.random.default_rng(seed)
    S = load_sources(ext, ext2, notes, hand)

    def merge(*names):
        return [x for n in names if n in S for x in S[n]]

    groups = {
        "jackhhao_jailbreak": (["jackhhao_jailbreak"], "published labels"),
        "spml_chatbot": (["spml_chatbot"], "published labels"),
        "geekyrakshit_injection": (["geekyrakshit_injection"], "published labels"),
        "deepset": (["deepset"], "published labels; shipped models saw a slice (contaminated)"),
        "safeguard": (["safeguard"], "published labels; shipped models saw a slice (contaminated)"),
        "gandalf_vs_instructions": (["gandalf_attack", "dolly_benign", "alpaca_benign"], "paired sources (shortcut risk)"),
        "injecagent_vs_notes": (["injecagent_dh", "injecagent_ds", "synthetic_persona_benign", "oasst_benign"],
                                "paired sources (shortcut risk)"),
        "injecagent_toolresp": (["injecagent_toolresp"], "minimal pairs: same tool response with / without the injected instruction"),
        "asb_vs_user_instructions": (["asb_attack", "injecagent_user_benign"], "paired sources (shortcut risk)"),
        "notes_D": (["notes_D"], "assistant-written, hand style"),
        "notes_A": (["notes_A"], "LLM-written"), "notes_B": (["notes_B"], "LLM-written"), "notes_C": (["notes_C"], "LLM-written"),
    }
    tests = {}
    for g, (names, _) in groups.items():
        data = subsample(merge(*names), cap, rng)
        if data and 0 < sum(y for _, y in data) < len(data):
            # the product normalises every write before scoring (confusables, spacing, leetspeak, invisible characters)
            tests[g] = ([normalise_text(t) for t, _ in data], np.array([y for _, y in data]))
        else:
            print(f"skip {g}: missing or single-class", flush=True)

    # shipped scorers need feature rows: attach a random benchmark context to every text (as in run_hybrid)
    entries = load_benchmark(benchmark)
    r2 = random.Random(1)
    ext_f = SemanticFeatureExtractor()

    def feats(texts):
        recs = []
        for t in texts:
            d = copy.deepcopy(r2.choice(entries))
            recs.append(dict(content=t, provenance=d.provenance, write_history=d.write_history, session_id=d.session_id,
                             last_query=d.last_query, memory_entries=d.memory_entries))
        return ext_f.extract_batch(recs)

    def wmax(fn, texts):
        """max over the note and its sentence windows (same rule as the shipped hybrid)"""
        groups_ = [windows(t) for t in texts]
        flat = np.asarray(fn([w for g in groups_ for w in g]))
        out, i = [], 0
        for g in groups_:
            out.append(flat[i:i + len(g)].max())
            i += len(g)
        return np.array(out)

    scorers = {}
    for name, path in (("hybrid_shipped", "models/classifier_hybrid.pkl"), ("hybrid_instr", "models/classifier_hybrid_instr.pkl")):
        if Path(path).exists():
            det = load_detector(path)
            n_feat = len(det._feature_names)
            scorers[name] = (lambda texts, det=det, n=n_feat: det.predict_proba_text(feats(texts)[:, :n], texts)[:, 0])
    if Path("models/finetuned_minilm_instr.pt").exists():
        from scripts.run_finetuned import NAME, Clf, predict
        from transformers import AutoTokenizer
        tok = AutoTokenizer.from_pretrained(NAME)
        ft = Clf()
        ft.load_state_dict(torch.load("models/finetuned_minilm_instr.pt"))
        scorers["finetuned_instr"] = lambda texts: wmax(lambda x: predict(ft, tok, x), texts)
    try:
        from transformers import pipeline
        pipe = pipeline("text-classification", model="protectai/deberta-v3-base-prompt-injection-v2",
                        truncation=True, max_length=512)

        def deb(texts):
            res = pipe(list(texts), batch_size=16)
            return np.array([r["score"] if r["label"].upper().startswith("INJ") else 1 - r["score"] for r in res])
        scorers["protectai_deberta"] = lambda texts: wmax(deb, texts)
    except Exception as e:     # offline or model moved: say so in the output instead of failing the whole run
        print(f"protectai baseline unavailable: {type(e).__name__}: {str(e)[:100]}", flush=True)

    enc = FeatureExtractor().encoder
    embed = lambda texts: enc.encode(list(texts), normalize_embeddings=True, batch_size=64, show_progress_bar=False)
    always = [(t, y) for y, t in tsv(train_extra)] + [(r["text"][:MAXCH], int(r["label"] == 0))
                                                      for r in jl(notes) if r["split"] == "train"]
    result: dict = {}
    raw_scores: dict = {}
    if only and not tag:     # partial rerun: keep the groups that are not being recomputed
        if (out / "multisource.json").exists() and (out / "multisource_scores.json").exists():
            result = json.loads((out / "multisource.json").read_text())
            raw_scores = json.loads((out / "multisource_scores.json").read_text())
    for g, (texts, y) in tests.items():
        if only and g not in only.split(","):
            continue
        # sources of one family share strings (InjecAgent attacker instructions appear inside its tool responses), so a
        # held-out group removes the whole family from the leave-one-out training pool
        fam = lambda n: n.split("_")[0] if n.startswith(("injecagent", "asb")) else n
        held = {n for n in S if fam(n) in {fam(h) for h in groups[g][0]}}
        pool = list(always) if not g.startswith("notes_") else list(always)
        for name, rows_ in S.items():
            if name in held or name.startswith("notes_"):
                continue
            pool += rows_[:loso_per_source]
        pt = [t for t, _ in pool]
        py = np.array([v for _, v in pool])
        tf = TfidfVectorizer(ngram_range=(1, 2), min_df=2, sublinear_tf=True)
        lr_t = LogisticRegression(max_iter=2000, C=4.0, class_weight="balanced").fit(tf.fit_transform(pt), py)
        lr_e = LogisticRegression(max_iter=2000, C=4.0, class_weight="balanced").fit(embed(pt), py)
        per = {"tfidf_loso": lr_t.predict_proba(tf.transform(texts))[:, 1], "embed_loso": lr_e.predict_proba(embed(texts))[:, 1]}
        for name, fn in scorers.items():
            per[name] = np.asarray(fn(texts))
        # fusions fixed in advance (unweighted means of P(attack)); nothing here is tuned on the test groups
        if "protectai_deberta" in per and "hybrid_instr" in per:
            per["fuse_hybrid+deb"] = (per["hybrid_instr"] + per["protectai_deberta"]) / 2
        if "protectai_deberta" in per and "finetuned_instr" in per:
            per["fuse_ft+deb"] = (per["finetuned_instr"] + per["protectai_deberta"]) / 2
        if all(k in per for k in ("protectai_deberta", "finetuned_instr", "hybrid_instr")):
            per["fuse_all3"] = (per["hybrid_instr"] + per["finetuned_instr"] + per["protectai_deberta"]) / 3
        raw_scores[g] = {"y": y.tolist(), **{k: [round(float(x), 5) for x in v] for k, v in per.items()}}
        result[g] = {"note": groups[g][1], "n": int(len(y)), "n_attack": int(y.sum()), "train_rows_loso": len(pt)}
        for name, p in per.items():
            pred = p >= 0.5
            result[g][name] = {"auroc": float(roc_auc_score(y, p)), "auroc_ci95": boot_auc(y, p, nrng),
                               "recall": float(pred[y == 1].mean()), "false_alarm": float(pred[y == 0].mean()),
                               "far_at_90_recall": far_at_recall(y, p)}
        print(g, {k: round(v["auroc"], 3) for k, v in result[g].items() if isinstance(v, dict)}, flush=True)

    out.mkdir(exist_ok=True)
    (out / f"multisource{tag}.json").write_text(json.dumps(result, indent=2))
    (out / f"multisource_scores{tag}.json").write_text(json.dumps(raw_scores))
    names = [n for n in ("hybrid_shipped", "hybrid_instr", "finetuned_instr", "protectai_deberta", "tfidf_loso", "embed_loso",
                         "fuse_hybrid+deb", "fuse_ft+deb", "fuse_all3")
             if any(n in v for v in result.values())]
    lines = ["| Test group (n, attacks) | Note | " + " | ".join(names) + " |", "|---|---|" + "---|" * len(names)]
    for g, v in result.items():
        cells = [f"{v[n]['auroc']:.3f} [{v[n]['auroc_ci95'][0]:.2f},{v[n]['auroc_ci95'][1]:.2f}]" if n in v else "n/a" for n in names]
        lines.append(f"| {g} ({v['n']}, {v['n_attack']}) | {v['note']} | " + " | ".join(cells) + " |")
    lines += ["", "False-alarm rate at threshold 0.5 (benign flagged):", "",
              "| Test group | " + " | ".join(names) + " |", "|---|" + "---|" * len(names)]
    for g, v in result.items():
        lines.append(f"| {g} | " + " | ".join(f"{v[n]['false_alarm']:.2f}" if n in v else "n/a" for n in names) + " |")
    lines += ["", "Recall at threshold 0.5:", "", "| Test group | " + " | ".join(names) + " |", "|---|" + "---|" * len(names)]
    for g, v in result.items():
        lines.append(f"| {g} | " + " | ".join(f"{v[n]['recall']:.2f}" if n in v else "n/a" for n in names) + " |")
    (out / f"multisource{tag}.md").write_text("\n".join(lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    app()
